2: /**
3:  * ntg-run — thin wrapper for `agy` that injects the NTG_ROLE marker so the
4:  * primary review gate can attribute the session's primary role on AGY 1.2/1.3,
5:  * where `--agent` no longer writes the role body into the transcript (issue #64,
6:  * convention from PR #71). Verified on CLI 1.3.1.
7:  *
8:  * Marker is injected only for gated roles (bulldozer, piledriver) — the roles the
9:  * gate actually enforces. Other agents pass through unchanged so the gate stays
10:  * out of their way (PR #71 provenance boundary). If the prompt already contains
11:  * an NTG_ROLE marker, it is left alone — no double injection.
12:  *
13:  * Usage:
14:  *   ntg-run --agent bulldozer -p "do the thing"
15:  *   ntg-run --agent piledriver --model gemini-3.1-pro -p "plan it" -- --passthrough
16:  *   ntg-run --ledger /path/to/ledger.json --agent bulldozer -p "do the thing"
17:  *
18:  * Anything after `--` passes verbatim to agy.
19:  */
20: import { spawn } from "node:child_process";
21: import process from "node:process";
22: import { acquireLedgerLock } from "./ledger-lock.mjs";
23: 
24: const GATED_ROLES = Object.freeze(new Set(["bulldozer", "piledriver"]));
25: const MARKER_RE = /^\s*NTG_ROLE\s*:/im;
26: 
27: /** Finds the prompt argument. Returns { index, prefix } — prefix is "" for `-p`/`--print`
28:  *  two-token form and "--print=" for the inline form, so the flag itself is preserved
29:  *  when the marker is prepended. "-p=..." is deliberately skipped: it would collide
30:  *  with bundled short flags like `-pm`. */
31: function firstPromptIndex(args) {
32:   for (let index = 0; index < args.length; index += 1) {
33:     if (args[index] === "-p" || args[index] === "--print") {
34:       return { index: index + 1, prefix: "" };
35:     }
36:     if (args[index]?.startsWith("--print=")) {
37:       return { index, prefix: "--print=" };
38:     }
39:   }
40:   return { index: -1, prefix: "" };
41: }
42: 
43: function agentArg(args) {
44:   for (let index = 0; index < args.length; index += 1) {
45:     if (args[index] === "--agent" || args[index] === "-a") {
46:       return args[index + 1]?.trim().toLowerCase() ?? null;
47:     }
48:     if (args[index]?.startsWith("--agent=")) {
49:       return args[index].slice("--agent=".length).trim().toLowerCase();
50:     }
51:   }
52:   return null;
53: }
