55: function main() {
56:   const raw = process.argv.slice(2);
57:   const passthrough = raw.indexOf("--");
58:   const ours = passthrough === -1 ? raw : raw.slice(0, passthrough);
59:   const rest = passthrough === -1 ? [] : raw.slice(passthrough + 1);
