61:   // This wrapper-owned flag is never forwarded to agy.
62:   let ledgerPath;
63:   for (let index = 0; index < ours.length; index += 1) {
64:     if (ours[index] === "--ledger" || ours[index].startsWith("--ledger=")) {
65:       if (ledgerPath !== undefined) throw new TypeError("--ledger may only be specified once");
66:       const inline = ours[index].startsWith("--ledger=");
67:       ledgerPath = inline ? ours[index].slice("--ledger=".length) : ours[index + 1];
68:       if (!ledgerPath || ledgerPath.startsWith("-")) throw new TypeError("--ledger requires a file path");
69:       ours.splice(index, inline ? 1 : 2);
70:       index -= 1;
71:     }
72:   }
73:   // This wrapper owns signals itself; the lock only registers exit-cleanup.
74:   const release = ledgerPath ? acquireLedgerLock(ledgerPath, { handleSignals: false }) : () => {};
75:   const role = agentArg(ours);
76:   const prompt = firstPromptIndex(ours);
77:   const args = [...ours];
78: 
79:   if (role !== null && GATED_ROLES.has(role) && prompt.index !== -1 && prompt.index < args.length) {
80:     const text = args[prompt.index].slice(prompt.prefix.length);
81:     if (!MARKER_RE.test(text)) {
82:       args[prompt.index] = `${prompt.prefix}NTG_ROLE: ${role}\n${text}`;
83:     }
84:   }
85: 
86:   const agy = process.env.AGY_PATH ?? "agy";
87:   const child = spawn(agy, [...args, ...rest], { stdio: "inherit", env: process.env });
88:   let interrupted;
89:   const forward = signal => {
90:     interrupted = signal;
91:     child.kill(signal);
92:   };
93:   const onInterrupt = () => forward("SIGINT");
94:   const onTerminate = () => forward("SIGTERM");
95:   process.on("SIGINT", onInterrupt);
96:   process.on("SIGTERM", onTerminate);
97:   child.on("error", error => {
98:     console.error(error.message);
99:   });
100:   const onHangup = () => forward("SIGHUP");
101:   process.on("SIGHUP", onHangup);
102:   child.once("close", (code, signal) => {
103:     process.removeListener("SIGINT", onInterrupt);
104:     process.removeListener("SIGTERM", onTerminate);
105:     process.removeListener("SIGHUP", onHangup);
106:     release();
107:     const exitSignal = interrupted ?? signal;
108:     if (typeof code === "number" && code >= 0 && code <= 255) { process.exit(code); }
109:     process.exit(exitSignal === "SIGINT" ? 130 : exitSignal === "SIGTERM" ? 143 : exitSignal === "SIGHUP" ? 129 : 1);
110:   });
111: }
